package ai.wexy.platform.storage;

/**
 * Where a saved world's bytes live (W3.1; the creations platform design §8): the private B2 bucket ({@link
 * B2ObjectStore}), or a test's map that keeps the same rules. Keys are generated by the platform, never a client's; no
 * key or URL leaves this service. Every method blocks: callers run it on the storage scheduler, never the event loop.
 * A failure is {@link StorageUnavailable}; the database decides what it means (I8).
 */
public interface ObjectStore {

    /** What a write left: B2's version id of these bytes, or null when the store keeps none. */
    record Written(String versionId) {
    }

    /** Whether the store is set up; when not, every call throws {@link StorageUnavailable}. */
    boolean configured();

    /**
     * Writes `bytes` under `key`, the store checking them against `md5Base64` (their MD5, base64, as Content-MD5), so a
     * write that arrives altered is refused rather than kept. A retry writes the same bytes to the same key.
     */
    Written put(String key, byte[] bytes, String contentType, String md5Base64);

    /**
     * The bytes under `key` (at `versionId` when one is given), or null when there are none. More than `maxBytes` is a
     * failure: a stored object is never larger than what was checked before it was written.
     */
    byte[] get(String key, String versionId, int maxBytes);

    /**
     * Erases `key`: the version `versionId` when known, else every version of it. Deleting what is not there succeeds,
     * so a repeated job is harmless.
     */
    void delete(String key, String versionId);

    /** The store could not answer: B2 down, slow, refusing our key, or not set up. Never a client's fault. */
    final class StorageUnavailable extends RuntimeException {
        public StorageUnavailable(String message, Throwable cause) {
            super(message, cause, false, false);
        }
    }
}
